files.site/styles.css:
* { box-sizing: border-box; }
body { margin: 0; font: 16px/1.5 system-ui, sans-serif; }

.site-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; }
.logo { font-weight: 700; text-decoration: none; color: #111; }

.nav { display: flex; flex-wrap: wrap; width: 360px; }
.nav a { padding: 8px 20px; color: #333; text-decoration: none; }

.hero { position: relative; padding: 48px 24px; }
.hero-video { width: 960px; height: auto; display: block; }
.hero h1 { font-size: 48px; margin: 24px 0 0; }
